package net.civeira.phylax.features.access.platformidentity.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.platformidentity.domain.PlatformIdentity;
import net.civeira.phylax.features.access.platformidentity.domain.gateway.PlatformIdentityCursor;
import net.civeira.phylax.features.access.platformidentity.domain.gateway.PlatformIdentityFilter;

class PlatformIdentitySlider extends Slider<PlatformIdentity> {

  /**
   * @autogenerated SlideGenerator
   */
  private final PlatformIdentityCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final PlatformIdentityFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<PlatformIdentityFilter, PlatformIdentityCursor, Iterator<PlatformIdentity>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  PlatformIdentitySlider(final Iterator<PlatformIdentity> multi, final int limit,
      final BiFunction<PlatformIdentityFilter, PlatformIdentityCursor, Iterator<PlatformIdentity>> gateway,
      final PlatformIdentityFilter filter, final PlatformIdentityCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param platformIdentitys
   * @param limit
   * @return
   */
  @Override
  public Iterator<PlatformIdentity> next(List<PlatformIdentity> platformIdentitys, int limit) {
    PlatformIdentity last = platformIdentitys.get(platformIdentitys.size() - 1);
    PlatformIdentityCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
